// Unified category tree for the storefront. API mode reads /categories (see data.ts getCategoryTree/getCategoryPage);
// demo mode uses src/data/category-tree.json (generated by scripts/build-category-tree.mjs from the API's
// database/data/category_tree.json) and maps the bundled catalog onto nodes with the same matcher as the API.
import treeData from "@/data/category-tree.json";
import catalogData from "@/data/catalog.json";
import { buildIndex, matchCategory, type MatchNode } from "./categoryMatch";
import { priceBdt } from "./pricing";
import type { MarketId, Product, StoreMode } from "./types";

export const PRICING_GROUPS = ["electronics", "fashion", "beauty", "grocery", "home"] as const;

/** One node as the API returns it (GET /categories); `count` is the visible product count of the subtree. */
export type CatNode = {
  path: string;
  slug?: string;
  name: string;
  nameBn?: string | null;
  icon: string;
  image?: string | null;
  depth: number;
  featured?: boolean;
  stores: MarketId[];
  count?: number;
  children: CatNode[];
};

export type CatCrumb = { path: string; name: string; nameBn?: string | null };

export type CategoryPageData = {
  node: CatNode;
  breadcrumbs: CatCrumb[];
  children: CatNode[];
  siblings: CatNode[];
  brands: { name: string; count: number }[];
  priceRange: { minBdt: number; maxBdt: number } | null;
  available: boolean;
};

type RawNode = Omit<CatNode, "children" | "stores"> & { stores: string[]; keywords: string[]; group: string; children: RawNode[] };

const RAW = (treeData as unknown as { tree: RawNode[] }).tree;
const PRODUCTS = (catalogData as { products: Product[] }).products;

// ---------- flat index (built once per server process) ----------
const FLAT = new Map<string, { node: RawNode; parent: string | null }>();
(function walk(nodes: RawNode[], parent: string | null) {
  for (const n of nodes) {
    FLAT.set(n.path, { node: n, parent });
    walk(n.children, n.path);
  }
})(RAW, null);

let productPaths: Map<string, string> | null = null;
/** productId -> deepest matching node path for the bundled catalog (cached). */
function productMap(): Map<string, string> {
  if (productPaths) return productPaths;
  const nodes: MatchNode[] = [...FLAT.values()].map(({ node, parent }) => ({
    path: node.path,
    name: node.name,
    keywords: node.keywords,
    stores: node.stores,
    depth: node.depth,
    hasChildren: node.children.length > 0,
    parent,
  }));
  const index = buildIndex(nodes);
  productPaths = new Map();
  for (const p of PRODUCTS) {
    const path = matchCategory(index, p.market, p.title, p.categoryPath ?? []);
    if (path) productPaths.set(p.id, path);
  }
  return productPaths;
}

export function productCategoryPath(p: Pick<Product, "id">): string | null {
  return productMap().get(p.id) ?? null;
}

const isGroup = (c: string) => (PRICING_GROUPS as readonly string[]).includes(c);

/** Search filter: a tree path matches the node and its descendants; the five pricing groups keep the legacy filter. */
export function inCategory(p: Product, category: string): boolean {
  if (isGroup(category) || !FLAT.has(category)) return p.category === category;
  const path = productCategoryPath(p);
  return !!path && (path === category || path.startsWith(category + "/"));
}

// ---------- local (demo) tree ----------
let localCounts: Map<string, Record<string, number>> | null = null;
function counts() {
  if (localCounts) return localCounts;
  localCounts = new Map();
  for (const p of PRODUCTS) {
    const path = productCategoryPath(p);
    if (!path) continue;
    for (let cur: string | null = path; cur; cur = FLAT.get(cur)?.parent ?? null) {
      const c = localCounts.get(cur) ?? {};
      c.all = (c.all ?? 0) + 1;
      c[p.market] = (c[p.market] ?? 0) + 1;
      localCounts.set(cur, c);
    }
  }
  return localCounts;
}

const sells = (n: { stores: string[] }, store: StoreMode) => store === "all" || n.stores.includes(store);

function present(n: RawNode, store: StoreMode, depth?: number): CatNode {
  return {
    path: n.path,
    slug: n.slug,
    name: n.name,
    nameBn: n.nameBn,
    icon: n.icon,
    depth: n.depth,
    featured: n.featured,
    stores: n.stores as MarketId[],
    count: counts().get(n.path)?.[store] ?? 0,
    children: !depth || n.depth < depth ? n.children.filter((c) => sells(c, store)).map((c) => present(c, store, depth)) : [],
  };
}

export function localTree(store: StoreMode = "all", depth?: number): CatNode[] {
  return RAW.filter((n) => sells(n, store)).map((n) => present(n, store, depth));
}

export function localCategoryPage(path: string, store: StoreMode = "all"): CategoryPageData | null {
  const hit = FLAT.get(path);
  if (!hit) return null;
  const crumbs: CatCrumb[] = [];
  for (let cur: string | null = path; cur; cur = FLAT.get(cur)?.parent ?? null) {
    const n = FLAT.get(cur)!.node;
    crumbs.unshift({ path: n.path, name: n.name, nameBn: n.nameBn });
  }
  const siblings = (hit.parent ? FLAT.get(hit.parent)!.node.children : RAW).filter((n) => n.path !== path && sells(n, store));
  const inNode = PRODUCTS.filter((p) => (store === "all" || p.market === store) && inCategory(p, path));
  const brands = new Map<string, number>();
  for (const p of inNode) if (p.brand) brands.set(p.brand, (brands.get(p.brand) ?? 0) + 1);
  const prices = inNode.map(priceBdt).filter((x) => x > 0);
  return {
    node: { ...present(hit.node, store, hit.node.depth), children: [] },
    breadcrumbs: crumbs,
    children: hit.node.children.filter((c) => sells(c, store)).map((c) => ({ ...present(c, store, c.depth) })),
    siblings: siblings.map((s) => ({ ...present(s, store, s.depth) })),
    brands: [...brands].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 12).map(([name, count]) => ({ name, count })),
    priceRange: prices.length ? { minBdt: Math.min(...prices), maxBdt: Math.max(...prices) } : null,
    available: sells(hit.node, store),
  };
}

/** Every node path (sitemap). */
export function allCategoryPaths(): string[] {
  return [...FLAT.keys()];
}

export function isCategoryPath(path: string): boolean {
  return FLAT.has(path);
}
